     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
     4	import { ZimmTextInput } from 'app/components/ui-kits/atoms/zimmTextInput';
     5	import { ZimmModal } from 'app/components/ui-kits/atoms/zimmModal';
     6	import { isSafeHref } from 'app/utils/safeHref';
     7	import { useZimmModal } from 'app/hooks/useZimmModal';
     8	
     9	const ZIMM_SUBSCRIBE_MODAL_RECIPE = 'ZimmSubscribeModal';
    10	const ZIMM_MODAL_RECIPE = 'ZimmModal';
    11	// alias/size/modal/footer (480px). Provisional — kept as a named rem reference until the UI
    12	// designer confirms a shared modal-size token; every dialog built on ZimmModal supplies its own
    13	// maxWidth today rather than inheriting a guessed default.
    14	const MODAL_MAX_WIDTH = '30rem';
    15	
    16	// HPC-037 copy — update when UX supplies final content.
    17	const PRIVACY_CONSENT_COPY = 'By providing your details, you agree to receive email updates from Zimmermann. View our';
    18	const ACCESSIBILITY_DISCLAIMER_COPY =
    19	  'Zimmermann is committed to providing accessible services. ' +
    20	  'If you experience any difficulty, please contact us for assistance.';
    21	
    22	type ZimmSubscribeModalProps = {
    23	  isOpen: boolean;
    24	  onClose: () => void;
    25	  onSubmit: (firstName: string, lastName: string) => void;
    26	  privacyPolicyHref: string;
    27	};
    28	
    29	/**
    30	 * The HPC-035 first/last-name capture modal, built on the generic ZimmModal atom. Rendered
    31	 * through a portal (via ZimmModal) so the overlay escapes the caller's stacking context.
    32	 *
    33	 * @param props see ZimmSubscribeModalProps
    34	 */
    35	export const ZimmSubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: ZimmSubscribeModalProps) => {
    36	  const { mounted, trapRef, firstFocusRef } = useZimmModal({ isOpen, onClose });
    37	  const chrome = useMultiStyleConfig(ZIMM_MODAL_RECIPE, {});
    38	  const styles = useMultiStyleConfig(ZIMM_SUBSCRIBE_MODAL_RECIPE, {});
    39	
    40	  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    41	    e.preventDefault();
    42	    const form = e.currentTarget;
    43	    // namedItem returns Element | RadioNodeList | null. The cast keeps `| null` rather than
    44	    // asserting it away — these fields are always single <input>s rendered by ZimmTextInput,
    45	    // but a missing field must stay a null the `?.` below can actually catch. Same pattern as
    46	    // zimmInputAction's handleSubmit.
    47	    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement | null)?.value ?? '';
    48	    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement | null)?.value ?? '';
    49	    onSubmit(firstName.trim(), lastName.trim());
    50	  };
    51	
    52	  return (
    53	    <ZimmModal
    54	      isOpen={isOpen}
    55	      mounted={mounted}
    56	      onClose={onClose}
    57	      maxWidth={MODAL_MAX_WIDTH}
    58	      labelledBy="zimm-subscribe-modal-title"
    59	      describedBy="zimm-subscribe-modal-consent"
    60	    >
    61	      <form ref={trapRef as React.RefObject<HTMLFormElement>} onSubmit={handleFormSubmit} noValidate>
    62	        {/* Title */}
    63	        <chakra.h2 id="zimm-subscribe-modal-title" __css={styles.title}>
    64	          Join Us
    65	        </chakra.h2>
    66	
    67	        {/* First Name */}
    68	        <chakra.div ref={firstFocusRef} __css={styles.field}>
    69	          <ZimmTextInput label="First Name" name="firstName" />
    70	        </chakra.div>
    71	
    72	        {/* Last Name */}
    73	        <chakra.div __css={styles.fieldLast}>
    74	          <ZimmTextInput label="Last Name" name="lastName" />
    75	        </chakra.div>
    76	
    77	        {/* Privacy consent copy (HPC-037) */}
    78	        <chakra.p id="zimm-subscribe-modal-consent" __css={styles.consent}>
    79	          {PRIVACY_CONSENT_COPY}{' '}
    80	          {/* Same guard as the contact channels: privacyPolicyHref is a prop, so a caller can
    81	              supply anything. Unsafe or absent renders the label as plain text rather than an
    82	              anchor that goes nowhere. */}
    83	          {isSafeHref(privacyPolicyHref) ? (
    84	            <chakra.a href={privacyPolicyHref} __css={styles.consentLink}>
    85	              Privacy Policy
    86	            </chakra.a>
    87	          ) : (
    88	            <chakra.span __css={styles.consentLink}>Privacy Policy</chakra.span>
    89	          )}
    90	          .
    91	        </chakra.p>
    92	
    93	        {/* Accessibility disclaimer (HPC-037) */}
    94	        <chakra.p __css={styles.disclaimer}>{ACCESSIBILITY_DISCLAIMER_COPY}</chakra.p>
    95	
    96	        {/* Actions */}
    97	        <chakra.div __css={chrome.actions}>
    98	          <ZimmButton variant="secondary" size="medium" label="Cancel" type="button" onClick={onClose} />
    99	          <ZimmButton variant="primary" size="medium" label="Continue" type="submit" />
   100	        </chakra.div>
   101	      </form>
   102	    </ZimmModal>
   103	  );
   104	};

