    10	export default meta;
    11	type Story = StoryObj<typeof ZimmSubscribeModal>;
    12	
    13	/**
    14	 * Isolated mount — open by default so the panel renders without needing a trigger. Full dialog
    15	 * mechanics (focus entry, Tab trap, scroll lock, Escape) are mutation-tested at the footer
    16	 * assembly level (footer/index.stories.tsx's SubscribeModalOpen) and at the hook level
    17	 * (hooks/useZimmModal.test.tsx); testing.md says prove behaviour once, at the cheapest layer.
    18	 * This story is for components.md's per-exported-component requirement and the visual panel.
    19	 */
    20	export const Default: Story = {
    21	  render: () => {
    22	    const [isOpen, setIsOpen] = useState(true);
    23	    return (
    24	      <ZimmSubscribeModal
    25	        isOpen={isOpen}
    26	        onClose={() => setIsOpen(false)}
    27	        onSubmit={() => setIsOpen(false)}
    28	        privacyPolicyHref="/privacy-policy"
    29	      />
    30	    );
    31	  },
    32	  // ZimmModal gates its portal on `mounted`, which useZimmModal flips in a useEffect, so the
    33	  // dialog does not exist on the first render pass. These must be async finders — a synchronous
    34	  // getByRole runs before that re-render and fails with "unable to find role dialog".
    35	  play: async () => {
    36	    const doc = within(document.body);
    37	    await expect(await doc.findByRole('dialog')).toBeInTheDocument();
    38	    await expect(await doc.findByRole('heading', { name: /join us/i })).toBeInTheDocument();
    39	    await expect(await doc.findByRole('link', { name: /privacy policy/i })).toBeInTheDocument();
    40	  },
    41	};

